/* RepairlyLabs — accessible, dependency-free customer SPA and admin console */
const app=document.getElementById('app');
const dialogRoot=document.getElementById('dialog-root');
const toastRoot=document.getElementById('toast-root');
const state={config:null,products:[],cart:[],admin:null,adminTab:'overview',adminData:null,models:[],shop:{brand:'',category:'',q:'',model:'',limit:24},shopData:null};
try{state.cart=JSON.parse(localStorage.getItem('repairlylabs-cart')||'[]');if(!Array.isArray(state.cart))state.cart=[];}catch{state.cart=[];}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const biz=()=>state.config?.settings||{};
const brands=()=>state.config?.brands?.map(b=>b.brand)||[];
const saved=()=>{try{localStorage.setItem('repairlylabs-cart',JSON.stringify(state.cart));}catch{}};
const dateLocal=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const paths={
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',up:'<path d="M7 17 17 7M7 7h10v10"/>',chev:'<path d="m9 18 6-6-6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',x:'<path d="M5 5 19 19M19 5 5 19"/>',shopping:'<path d="M3 4h2l2 11h12l2-8H6M9 20h.01M18 20h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',shield:'<path d="M12 2 20 6v6c0 5-3.5 8-8 10-4.5-2-8-5-8-10V6l8-4Z"/><path d="m9 12 2 2 4-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',map:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M11 18h2"/>',call:'<path d="M6 3H3l-1 5c2 7 7 12 14 14l5-1v-3l-5-3-3 2a14 14 0 0 1-6-6l2-3Z"/>',monitor:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 18h8"/>',battery:'<rect x="2" y="6" width="18" height="12" rx="2"/><path d="M22 10v4m-12-5-3 4h5l-2 3"/>',plug:'<path d="M8 2v6m8-6v6M6 8h12v4a6 6 0 0 1-12 0V8Zm6 10v4"/>',droplets:'<path d="M12 2c-4 6-7 9-7 13a7 7 0 0 0 14 0c0-4-3-7-7-13Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',camera:'<rect x="2" y="6" width="20" height="15" rx="3"/><circle cx="12" cy="13" r="4"/><path d="m7 6 1.5-3h7L17 6"/>',speaker:'<path d="m3 9 5 0 6-5v16l-6-5H3V9Zm15-2a7 7 0 0 1 0 10m2-14a12 12 0 0 1 0 18"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3m-3-6-2 2M8 16l-2 2m0-12 2 2m8 8 2 2"/><circle cx="12" cy="12" r="4"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-10 11 10 6 10-6"/>',package:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 5 9-5m-9 5v10m-4-16 9 5"/>',truck:'<path d="M2 5h12v12H2V5Zm12 4h5l3 4v4h-8V9ZM7 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm12 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/>',spark:'<path d="m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7L12 2Z"/>',repair:'<path d="M21 3a6 6 0 0 1-8 7L5 18a3 3 0 1 0 4 4l8-8a6 6 0 0 0 4-11Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',message:'<path d="M21 4H3v15h4l5 3 5-3h4V4Z"/>',clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="M9 12h6m-6 4h6"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 14h4v7H6a2 2 0 0 1-2-2v-5Zm12 0h4v5a2 2 0 0 1-2 2h-2v-7Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m3 6 9 7 9-7"/>',location:'<path d="m3 7 6-3 6 3 6-3v13l-6 3-6-3-6 3V7Zm6-3v13m6-10v13"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',trash:'<path d="M4 7h16M10 3h4m-8 4 1 14h10l1-14M10 10v8m4-8v8"/>',edit:'<path d="m3 17-1 5 5-1L20 8l-5-5L3 17Zm10-12 5 5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 19v3h16v-3"/>',logout:'<path d="M10 4H4v16h6m4-12 4 4-4 4m4-4H8"/>',dashboard:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="5" rx="2"/><rect x="13" y="10" width="8" height="11" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',star:'<path d="m12 2 3 6 7 .9-5 5 .9 7.1-5.9-3.3-5.9 3.3.9-7.1-5-5L9 8Z"/>',save:'<path d="M4 3h14l3 3v15H3V3h1Zm3 0v7h9V3M7 21v-8h10v8"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'};
function icon(name,size=22){const alias={'monitor-smartphone':'monitor','battery-charging':'battery','plug-zap':'plug','volume-2':'speaker','settings-2':'settings','layers-3':'layers','wrench':'repair'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[alias[name]||name]||paths.spark}</svg>`;}
async function api(path,opts={}){const conf={method:opts.method||'GET',headers:{},credentials:'same-origin'};if(opts.body!==undefined){conf.body=JSON.stringify(opts.body);conf.headers['Content-Type']='application/json';}if(state.admin?.csrf&&conf.method!=='GET')conf.headers['X-CSRF-Token']=state.admin.csrf;const r=await fetch(path,conf);let data;try{data=await r.json();}catch{data={};}if(!r.ok)throw new Error(data.error||`Request failed (${r.status})`);return data;}
function toast(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'info':'checkcircle',19)+`<span>${esc(msg)}</span>`;toastRoot.append(el);setTimeout(()=>{el.remove();},5000);}
function loadingButton(btn,on){if(!btn)return;if(on){btn.dataset.original=btn.innerHTML;btn.disabled=true;btn.textContent='Please wait…';}else{btn.disabled=false;btn.innerHTML=btn.dataset.original||'Continue';}}
const logoIcon='<svg width="21" height="21" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="2" y="2.5" width="11.5" height="19" rx="2.8" stroke="#081420" stroke-width="1.8" fill="#081420" fill-opacity="0.14"/><line x1="5.5" y1="5.5" x2="10" y2="5.5" stroke="#081420" stroke-width="1.5" stroke-linecap="round"/><line x1="6" y1="18.5" x2="9.5" y2="18.5" stroke="#081420" stroke-width="1.5" stroke-linecap="round"/><path d="M22 2.5a4.2 4.2 0 0 1-5.5 5.5l-5 5a2 2 0 1 0 2.8 2.8l5-5a4.2 4.2 0 0 0 2.7-8.3z" fill="#ffffff" stroke="#081420" stroke-width="1.3" stroke-linejoin="round"/><circle cx="21" cy="3.5" r="1.1" fill="#081420"/></svg>';
function logo(){const name=esc(biz().business_name||'RepairlyLabs');const styled=name.replace(/labs$/i,'<em>Labs</em>').replace(/fix$/i,'<em>Fix</em>');return `<a href="/" class="logo" data-link aria-label="${name} home"><span class="logo-mark">${logoIcon}</span><span>${styled}</span></a>`;}
const navItems=[['/','Home'],['/repairs','Repairs'],['/parts','Spare parts'],['/track','Track request'],['/about','Our approach'],['/contact','Contact']];
function header(path){return `<header class="navbar" id="navbar"><div class="container nav-shell">${logo()}<nav class="nav-links" aria-label="Primary">${navItems.map(([href,label])=>`<a href="${href}" data-link class="${path===href?'active':''}">${label}</a>`).join('')}</nav><div class="nav-actions"><button type="button" class="cart-trigger" data-action="cart" aria-label="Open cart">${icon('shopping',21)}<span class="cart-count" id="cart-count" ${cartQty()?'':'hidden'}>${cartQty()}</span></button><a href="/repairs#booking" data-link class="btn btn-primary btn-sm nav-book">Book a repair ${icon('arrow',16)}</a><button class="mobile-trigger" aria-label="Toggle navigation" aria-expanded="false" data-action="menu">${icon('menu',25)}</button></div></div><nav class="mobile-nav hide" id="mobile-nav">${navItems.map(([href,label])=>`<a href="${href}" data-link>${label}</a>`).join('')}<a href="/admin" data-link>Team login</a></nav></header>`;}
function footer(){const s=biz();return `<footer class="footer"><div class="container"><div class="footer-top"><div>${logo()}<p>${esc(s.tagline||'Care for every connection.') } A Varanasi-focused place to explore repair options and request phone parts.</p><span class="pill dark-pill">${icon('map',14)} Varanasi, Uttar Pradesh</span></div><div><h4>Explore</h4><div class="footer-col"><a href="/repairs" data-link>Repair services</a><a href="/parts" data-link>Spare parts</a><a href="/track" data-link>Track a request</a><a href="/about" data-link>How we work</a></div></div><div><h4>Get help</h4><div class="footer-col"><a href="/contact" data-link>Contact the team</a><a href="/repairs#booking" data-link>Request repair</a><a href="/parts" data-link>Part availability</a><a href="/admin" data-link>Team login</a></div></div><div><h4>Varanasi service area</h4><div class="footer-col"><span>${esc(s.address||'Varanasi, Uttar Pradesh, India')}</span>${s.phone?`<a href="tel:+91${esc(s.phone.replace(/\D/g,'').slice(-10))}">${esc(s.phone)}</a>`:''}${s.email?`<a href="mailto:${esc(s.email)}">${esc(s.email)}</a>`:''}${s.hours?`<span>${esc(s.hours)}</span>`:''}<span>Visit or pickup arrangements are confirmed after your request.</span></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(s.business_name||'RepairlyLabs')}. Built for clear, considered mobile care.</span><div class="foot-links"><a href="/contact" data-link>Contact</a><a href="/privacy" data-link>Privacy notice</a></div></div></div></footer>`;}
function frame(content,path='/'){document.title=(path==='/'?'Mobile Repair & Spare Parts':({'/repairs':'Book a Repair','/parts':'Spare Parts','/track':'Track Request','/about':'Our Approach','/contact':'Contact'}[path]||'RepairlyLabs'))+' | '+(biz().business_name||'RepairlyLabs');app.innerHTML=header(path)+`<main id="main-content">${content}</main>`+footer();updateCartCount();bindReveal();updateNavbar();}
function pageHero(parent,title,desc){return `<section class="page-hero"><div class="container"><div class="breadcrumb"><a href="/" data-link>Home</a> / <span>${esc(parent)}</span></div><h1>${title}</h1><p>${desc}</p></div></section>`;}
function heroPhone(){return `<div class="hero-scene" aria-hidden="true"><div class="orbit"></div><div class="orbit orbit-two"></div><div class="glowblob"></div><span class="scene-spark s1">✳</span><span class="scene-spark s2">✧</span><div class="hero-phone"><div class="hero-phone-screen"><div class="notch"></div><div class="screen-time">09:41</div><div class="screen-day">Always connected</div><div class="screen-halo"></div><div class="screen-bottom"><span></span><span></span><span></span></div></div></div><div class="float-chip chip-top">${icon('shield',27)}<div><strong>Clear repair choices</strong><small>Know before you approve</small></div></div><div class="float-chip chip-bottom">${icon('spark',27)}<div><strong>Find the right fit</strong><small>Model-first part search</small></div></div></div>`;}
function serviceCard(s,compact=false){return `<a href="/repairs?issue=${encodeURIComponent(s.slug)}#booking" data-link class="service-card ${compact?'compact':''} reveal"><span class="service-icon">${icon(s.icon,28)}</span>${s.tag?`<span class="service-tag">${esc(s.tag)}</span>`:''}<h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><span class="mini-arrow">${icon('up',18)}</span></a>`;}
const artIcons={display:'monitor',battery:'battery',port:'plug',panel:'layers',camera:'camera',speaker:'speaker',flex:'settings'};
function productArt(p){const type=['battery','port','panel','camera','speaker','flex'].includes(p.image_kind)?p.image_kind:'display';return `<div class="product-art ${type}"><span class="product-badge">${p.sample?'Example price':'Part listing'}</span><div class="art-device">${icon(artIcons[type],58)}</div></div>`;}
function productCard(p){return `<article class="product-card reveal">${productArt(p)}<div class="product-content"><span class="product-brand">${esc(p.brand)} · ${esc(p.category)}</span><h3>${esc(p.name)}</h3><p class="model">For ${esc(p.model)}</p><div class="product-bottom"><div class="price">${money(p.price)}<small>${p.sample?'Indicative only':'Listed price'}</small></div><button type="button" class="add-square" data-action="add" data-id="${p.id}" aria-label="Add ${esc(p.name)} to cart">${icon('plus',21)}</button></div><button class="link-arrow" data-action="detail" data-id="${p.id}" style="margin-top:14px;background:none;font-size:.77rem;color:#596978">View part details ${icon('chev',14)}</button></div></article>`;}
function home(){const ss=state.config.services;const featured=state.products.slice(0,4);frame(`<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="hero-badge"><span class="live-dot"></span> MOBILE CARE, REIMAGINED · VARANASI</div><h1>Back to <span>what <span class="highlight">matters.</span></span></h1><p class="lead">Cracked screen? Battery giving up? Looking for a phone part? One thoughtful place to explore repairs, find compatible options, and stay in the loop.</p><div class="hero-buttons"><a class="btn btn-primary" href="/repairs#booking" data-link>Book a repair ${icon('arrow')}</a><a class="btn btn-outline" href="/parts" data-link>Explore spare parts ${icon('chev')}</a></div><div class="hero-proof"><div class="proof">${icon('checkcircle',19)} Clear quote process</div><div class="proof">${icon('shield',19)} Part options explained</div><div class="proof">${icon('map',19)} Varanasi focused</div></div></div>${heroPhone()}</div><div class="hero-scroll"><span class="mouse"></span> Scroll to explore</div></section>
 <div class="brand-strip"><div class="brand-inner"><span class="brand-note">Explore popular brands</span>${[...brands().slice(0,13),...brands().slice(0,13)].map(b=>`<span class="brand-word">${esc(b)}</span>`).join('')}</div></div>
 <section class="section services"><div class="container"><div class="section-head"><div><div class="eyebrow reveal">WHAT WE HELP WITH</div><h2 class="reveal">A little damage shouldn't <span class="accent">stop everything.</span></h2></div><p class="muted reveal">From broken screens to puzzling faults, start with the problem. We'll take it from there, one clear step at a time.</p></div><div class="service-grid">${ss.map(s=>serviceCard(s,true)).join('')}</div><div style="text-align:center;margin-top:35px"><a href="/repairs" data-link class="btn btn-dark">Explore all repairs ${icon('arrow')}</a></div></div></section>
 <section class="section process"><div class="container process-grid"><div class="process-side reveal"><div class="eyebrow">THE PROCESS</div><h2>Good service starts with <span class="highlight">clarity.</span></h2><p>We make the request journey straightforward. No mystery pricing or promises before the actual device is assessed.</p><div class="process-visual"><span class="pill dark-pill">${icon('shield',14)} REQUEST JOURNEY</span><div class="visual-line"></div><div class="visual-status"><span>Request submitted</span>${icon('checkcircle',21)}</div><p style="font-size:.75rem;color:#99b7bc;margin-top:13px">Your reference makes it easy to follow up.</p><div class="visual-phone"></div></div></div><div class="steps reveal"><div class="step"><div class="step-num">01</div><div><h3>Tell us what's happening</h3><p>Choose a phone model, share the issue, and pick how you'd like to reach us.</p></div></div><div class="step"><div class="step-num">02</div><div><h3>Review the diagnosis</h3><p>After inspection, discuss repair options, available part grades, the price and any warranty.</p></div></div><div class="step"><div class="step-num">03</div><div><h3>Approve, then follow along</h3><p>The team updates your request's progress. You decide whether to go ahead with the work.</p></div></div></div></div></section>
 <section class="section parts-showcase"><div class="container"><div class="section-head"><div><div class="eyebrow reveal">THE PARTS DESK</div><h2 class="reveal">Parts that fit your <span class="accent">world.</span></h2></div><p class="muted reveal">Explore example listings across popular phones. The team confirms variant compatibility, availability and price before an order.</p></div><div class="category-chips">${['All parts',...state.config.categories.slice(0,5)].map((c,i)=>`<a href="/parts${i?'?category='+encodeURIComponent(c):''}" data-link class="chip ${!i?'active':''}">${esc(c)}</a>`).join('')}</div><div class="parts-grid">${featured.map(productCard).join('')}</div><p class="catalog-disclaimer">${icon('info',17)} Listed sample prices are illustrative, not live market quotes. Verify component grade, exact model, stock and warranty before purchasing.</p><div style="text-align:center;margin-top:34px"><a href="/parts" data-link class="btn btn-dark">Browse the parts desk ${icon('arrow')}</a></div></div></section>
 <section class="section belief"><div class="container belief-grid"><div class="reveal"><div class="eyebrow">OUR APPROACH</div><h2>Less guessing. <span class="accent">More knowing.</span></h2><p>Phones are personal. Before proceeding with a repair, you should understand what was found, what choices you have, and what they mean for your device.</p><div class="promise-list"><div class="promise-item"><div class="promise-ico">${icon('shield')}</div><div><strong>Options before approval</strong><span>Ask for a clear estimate and parts explanation first.</span></div></div><div class="promise-item"><div class="promise-ico">${icon('phone')}</div><div><strong>Every model has a path</strong><span>Can't find yours? Enter the model manually.</span></div></div><div class="promise-item"><div class="promise-ico">${icon('clipboard')}</div><div><strong>Track with your reference</strong><span>Use the reference and your phone number for status.</span></div></div></div><a href="/about" data-link class="link-arrow" style="margin-top:30px">More about our approach ${icon('arrow')}</a></div><div class="belief-art reveal"><div class="belief-center"><div class="pill">YOUR REPAIR, YOUR DECISION</div><strong style="margin-top:18px">A clearer repair journey.</strong><div class="belief-check">${icon('checkcircle',20)} Inspect the device</div><div class="belief-check">${icon('checkcircle',20)} Explain part options</div><div class="belief-check">${icon('checkcircle',20)} Confirm your go-ahead</div><div class="belief-check">${icon('checkcircle',20)} Update the status</div></div></div></div></section>
 ${faqBlock()}
 <section class="cta-strip"><div class="container cta-flex"><div><div class="eyebrow" style="color:#fff">MAKE THE FIRST MOVE</div><h2>Let's get your phone back in action.</h2><p>Tell us the issue. We'll help you take the next step.</p></div><a href="/repairs#booking" data-link class="btn btn-light">Start a repair request ${icon('arrow')}</a></div></section>`,'/');}
function faqBlock(){return `<section class="section faq"><div class="container faq-layout"><div class="reveal"><div class="eyebrow">GOOD TO KNOW</div><h2>Questions? <span class="accent">Answered.</span></h2><p class="muted">Still unsure about something? You can always send a message before creating a request.</p><a href="/contact" data-link class="link-arrow">Contact the team ${icon('arrow')}</a></div><div class="reveal"><details><summary>Can I book for a model that isn't listed?</summary><p>Yes. Choose the brand or “Other”, then type your exact phone model. The team checks whether the requested service or part can be supported.</p></details><details><summary>Are the parts original or compatible?</summary><p>Different part grades may be available. Every sample listing is illustrative. Ask the team to explain the component source, grade, warranty and model fit before you approve an order.</p></details><details><summary>Is the website price final?</summary><p>No. Sample parts have indicative prices only. The final part price, availability, applicable charges and any repair quotation need explicit confirmation from the team.</p></details><details><summary>Do you offer pickup or delivery?</summary><p>Pickup requests may be offered subject to your area and team availability. Delivery depends on current settings. You will get confirmation before any arrangement is made.</p></details><details><summary>How do I check my repair or part order?</summary><p>Use Track request with the reference ID shown after submitting and the same 10-digit mobile number you provided.</p></details></div></div></section>`;}
const areaChoices=['Sigra','Lanka','BHU area','Assi','Bhelupur','Mahmoorganj','Cantt','Nadesar','Lahurabir','Chetganj','Godowlia','Maldahiya','Pandeypur','Sarnath','Shivpur','Chitaipur','Ramnagar','Other / nearby'];
function brandSelect(name='brand',requiredValue=true,selected=''){return `<select name="${name}" id="${name}" ${requiredValue?'required':''}><option value="">Select brand</option>${brands().map(b=>`<option value="${esc(b)}" ${selected===b?'selected':''}>${esc(b)}</option>`).join('')}<option value="Other" ${selected==='Other'?'selected':''}>Other brand</option></select>`;}
function areaInput(){return `<input name="locality" list="areas" placeholder="e.g. Sigra / Lanka" autocomplete="address-level2" maxlength="100" required><datalist id="areas">${areaChoices.map(x=>`<option value="${esc(x)}"></option>`).join('')}</datalist>`;}
function consentField(){return `<div class="field span2" style="margin-top:4px"><label style="display:flex;align-items:flex-start;gap:11px;line-height:1.65;font-weight:600"><input style="width:18px;height:18px;min-height:18px;flex-shrink:0;margin-top:3px;accent-color:var(--orange)" type="checkbox" name="consent" required> I agree to be contacted about this request, and have read the <a href="/privacy" target="_blank" rel="noopener noreferrer" style="color:var(--orange);text-decoration:underline">privacy notice</a>.</label></div>`;}
function bookingForm(){const initialIssue=new URLSearchParams(location.search).get('issue')||'';const first=state.config.services.find(s=>s.slug===initialIssue);return `<form id="booking-form" data-form="booking" class="form-panel"><div class="pill">${icon('calendar',14)} REPAIR REQUEST</div><h3 style="margin-top:18px">Tell us about your phone.</h3><p class="form-intro">A few details are enough to begin. This is a request, not a confirmed appointment or quotation.</p><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" maxlength="100" placeholder="Full name" required></div><div class="field"><label for="phone">Mobile number *</label><input id="phone" name="phone" inputmode="tel" autocomplete="tel" maxlength="17" placeholder="10-digit number" required></div><div class="field"><label for="brand">Phone brand *</label>${brandSelect()}</div><div class="field"><label for="model">Phone model *</label><input id="model" name="model" list="model-options" maxlength="120" placeholder="Select brand, then model" required><datalist id="model-options"></datalist></div><div class="field"><label for="issue">What's the problem? *</label><select id="issue" name="issue" required><option value="">Select issue</option>${state.config.services.map(s=>`<option ${first?.title===s.title?'selected':''} value="${esc(s.title)}">${esc(s.title)}</option>`).join('')}<option value="Other / unsure">Other / unsure</option></select></div><div class="field"><label for="method">Service preference *</label><select id="method" name="method" required><option value="Discuss options">Discuss options first</option><option value="Visit workshop">Visit workshop (after confirmation)</option>${biz().pickup_enabled==='1'?'<option value="Request pickup">Request pickup (subject to availability)</option>':''}</select></div><div class="field"><label for="locality">Your area *</label>${areaInput()}</div><div class="field"><label for="date">Preferred date (optional)</label><input id="date" type="date" name="date" min="${dateLocal()}"><small>Request only; time is confirmed separately.</small></div><div class="field span2"><label for="address">Full address / landmark (required for pickup)</label><input id="address" name="address" maxlength="260" autocomplete="street-address" placeholder="House / street, landmark and PIN code for pickup"></div><div class="field span2"><label for="notes">Anything else we should know?</label><textarea id="notes" name="notes" maxlength="800" placeholder="When did it start? Any visible damage? Anything already tried?"></textarea></div><div class="hide"><label>Leave empty<input name="website" tabindex="-1" autocomplete="off"></label></div>${consentField()}</div><button type="submit" class="btn btn-primary" style="width:100%">Submit repair request ${icon('arrow')}</button><p class="form-note">${icon('shield',17)} ${esc(biz().terms||'You will receive a reference and the team will verify service availability and price before any work.')}</p></form>`;}
function repairs(){frame(`${pageHero('Repairs','Your phone deserves a <span class="highlight">second chance.</span>','Screen, battery, charging, camera or something harder to pin down. Explore the options and send us the details.')}
 <section class="section page-area"><div class="container"><div class="section-head"><div><div class="eyebrow">HOW CAN WE HELP?</div><h2>Find your repair.</h2></div><p class="muted">Every request begins with the details of your actual device.</p></div><div class="service-grid">${state.config.services.map(s=>serviceCard(s,true)).join('')}</div></div></section>
 <section class="section" id="booking"><div class="container booking-layout"><div class="reveal">${bookingForm()}</div><aside class="info-rail reveal"><div class="info-box">${icon('clipboard',30)}<h4>Know what happens next</h4><p>Your request is saved immediately with a unique reference. The team reviews it and contacts you to discuss next steps.</p></div><div class="info-box">${icon('shield',30)}<h4>No surprise online payment</h4><p>We do not collect payment through this website. Any diagnosis fee, parts estimate or work cost needs confirmation first.</p></div><div class="info-box">${icon('map',30)}<h4>Built around Varanasi</h4><p>Share your locality for practical arrangements. Pickup and workshop visits depend on availability and confirmation.</p></div><div class="info-box">${icon('headphones',30)}<h4>Need to talk first?</h4><p>Not sure which service to select? You can use the contact page to describe your problem.</p><a href="/contact" data-link class="link-arrow" style="margin-top:12px">Contact us ${icon('arrow',18)}</a></div></aside></div></section>`,'/repairs');}
function parts(){const params=new URLSearchParams(location.search);state.shop={brand:params.get('brand')||'',category:params.get('category')||'',q:params.get('q')||'',model:params.get('model')||'',limit:24};frame(`${pageHero('Spare parts','The right part. <span class="highlight">A better fix.</span>','Find example parts by phone, category and model. Actual compatibility, part grade, stock and price are confirmed with the team.')}
 <section class="section page-area"><div class="container"><div class="shop-layout"><aside class="filter-pane"><h3>Explore parts ${icon('filter',19)}</h3><div class="filter-title">Phone brand</div><select id="shop-brand" data-filter="brand"><option value="">All brands</option>${brands().map(b=>`<option value="${esc(b)}" ${state.shop.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select><div class="filter-title">Category</div><div class="filter-list" id="category-filters"><button data-category="" class="${!state.shop.category?'active':''}">All parts</button>${state.config.categories.map(c=>`<button data-category="${esc(c)}" class="${state.shop.category===c?'active':''}">${esc(c)}</button>`).join('')}</div><div class="filter-title">Specific model</div><input class="search-input" id="shop-model" placeholder="e.g. Galaxy S24" value="${esc(state.shop.model)}" maxlength="100"><div style="margin-top:19px"><button class="btn btn-ghost btn-sm" data-action="clear-filters" style="width:100%">Clear filters</button></div></aside><div><div class="shop-tools"><div class="input-icon">${icon('search',19)}<input id="shop-search" class="search-input" type="search" placeholder="Search a part, device or SKU" value="${esc(state.shop.q)}" aria-label="Search parts"></div><span class="shop-count" id="shop-count">Loading parts...</span></div><div id="shop-result" class="shop-grid"></div><div id="shop-more" style="text-align:center;margin-top:30px"></div><p class="catalog-disclaimer">${icon('info',18)} All DEMO listings show illustrative prices and stock quantities. Orders are requests, not confirmed purchases; staff verify exact variant, availability, terms and final cost.</p></div></div></div></section>`,'/parts');loadShop();}
async function loadShop(append=false){const out=document.getElementById('shop-result');if(!out)return;const u=new URLSearchParams();for(const k of ['brand','category','model','q'])if(state.shop[k])u.set(k,state.shop[k]);u.set('limit',String(state.shop.limit));const start=append?(state.shopData?.items.length||0):0;u.set('offset',String(start));try{const d=await api('/api/products?'+u);state.shopData=append?{...d,items:[...(state.shopData?.items||[]),...d.items]}:d;out.innerHTML=state.shopData.items.length?state.shopData.items.map(productCard).join(''):`<div class="empty-state" style="grid-column:1/-1">${icon('search',36)}<h3>No matching parts yet</h3><p>Try a different model, or ask the team to source a specific part.</p><a href="/contact" data-link class="btn btn-primary">Ask about a part ${icon('arrow')}</a></div>`;document.getElementById('shop-count').textContent=`${state.shopData.total} listing${state.shopData.total!==1?'s':''}`;document.getElementById('shop-more').innerHTML=state.shopData.items.length<d.total?`<button class="btn btn-ghost" data-action="more-parts">Load more parts ${icon('arrow')}</button>`:'';bindReveal();}catch(e){out.innerHTML=`<div class="empty-state" style="grid-column:1/-1">${esc(e.message)}</div>`;}}
function about(){frame(`${pageHero('Our approach','Care that starts with <span class="highlight">the details.</span>','Our website is designed around simple decisions, clear information, and a better way to organize phone repair requests in Varanasi.')}
 <section class="section"><div class="container two-col" style="align-items:center"><div class="reveal"><div class="eyebrow">THE IDEA</div><h2>Because your phone isn't <span class="accent">just a phone.</span></h2><p class="muted">It's your photos, work, family messages and everyday connection. That deserves a thoughtful process — a chance to understand the issue, review possible parts and decide what happens next.</p><p class="muted">We built this experience to make it easier to request a repair, explore spare parts, and track progress without losing a reference in a message thread.</p><div class="about-numbers"><div><strong>01</strong><small>Describe the issue</small></div><div><strong>02</strong><small>Discuss your options</small></div><div><strong>03</strong><small>Follow the request</small></div></div></div><div class="belief-art reveal"><div class="belief-center"><div class="pill">WHAT WE VALUE</div><strong style="margin-top:17px">The facts, before the fix.</strong><div class="belief-check">${icon('checkcircle',20)} Explain the diagnosis</div><div class="belief-check">${icon('checkcircle',20)} Discuss grade & compatibility</div><div class="belief-check">${icon('checkcircle',20)} Agree on work and cost</div><div class="belief-check">${icon('checkcircle',20)} Communicate next steps</div></div></div></div></section>
 <section class="section services"><div class="container"><div class="section-head"><div><div class="eyebrow">IMPORTANT DETAILS</div><h2>No claims we can't <span class="accent">stand behind.</span></h2></div></div><div class="three-col"><div class="info-box">${icon('shield',28)}<h3>Component choices</h3><p>“Original”, “OEM”, and “compatible” are not interchangeable. Ask for written component-grade details for your particular order.</p></div><div class="info-box">${icon('clock',28)}<h3>Timing is confirmed</h3><p>Repair time can vary with device condition, parts availability and workload. An estimate is not a guaranteed completion date.</p></div><div class="info-box">${icon('clipboard',28)}<h3>Warranty depends on work</h3><p>${esc(biz().warranty||'Warranty terms are confirmed per repair and part.')}</p></div></div></div></section>
 <section class="section"><div class="container"><div class="eyebrow">BEFORE YOU BOOK</div><h2>Service terms, <span class="accent">in plain English.</span></h2><p class="muted max-text">${esc(biz().terms||'You approve service after the quote.')}</p><p class="muted max-text">Please back up data where possible before submitting a device. Do not share your phone password or sensitive account credentials through this form. Any required access should be discussed directly with the team.</p><a href="/contact" data-link class="btn btn-primary">Ask us a question ${icon('arrow')}</a></div></section>`,'/about');}
function contact(){const s=biz();frame(`${pageHero('Contact','Talk to a <span class="highlight">real person.</span>','Ask about a repair, a hard-to-find part, service arrangements or anything else. Your message goes straight to the team dashboard.')}
 <section class="section page-area"><div class="container"><div class="contact-cards"><div class="contact-card">${icon('map',27)}<strong>Our service city</strong><p>${esc(s.address||'Varanasi, Uttar Pradesh, India')}</p></div><div class="contact-card">${icon('call',27)}<strong>Phone / WhatsApp</strong><p>${s.phone?`<a href="tel:+91${esc(s.phone.replace(/\D/g,'').slice(-10))}">${esc(s.phone)}</a>`:'Use this form to request a call back.'}${s.whatsapp?`<br><a href="https://wa.me/${esc(s.whatsapp.replace(/\D/g,''))}" target="_blank" rel="noopener noreferrer">Open WhatsApp</a>`:''}</p></div><div class="contact-card">${icon('clock',27)}<strong>Visit information</strong><p>${esc(s.hours||'Visit times shared after appointment confirmation.')}</p></div></div><div class="booking-layout"><form class="form-panel" data-form="contact"><div class="pill">${icon('message',15)} SEND A MESSAGE</div><h3 style="margin-top:17px">What can we help with?</h3><p class="form-intro">We won't ask for payment or phone unlock details in this form.</p><div class="form-grid"><div class="field"><label for="c-name">Your name *</label><input id="c-name" name="name" maxlength="100" autocomplete="name" required placeholder="Full name"></div><div class="field"><label for="c-phone">Mobile number *</label><input id="c-phone" name="phone" required maxlength="17" autocomplete="tel" inputmode="tel" placeholder="10-digit number"></div><div class="field span2"><label for="c-email">Email (optional)</label><input id="c-email" type="email" name="email" maxlength="180" autocomplete="email" placeholder="your@email.com"></div><div class="field span2"><label for="c-message">Your message *</label><textarea id="c-message" name="message" maxlength="1400" placeholder="Tell us your device, issue or part requirement" required></textarea></div><div class="hide"><input tabindex="-1" name="website" autocomplete="off"></div>${consentField()}</div><button type="submit" class="btn btn-primary" style="width:100%">Send your message ${icon('arrow')}</button></form><aside class="info-rail"><div class="info-box">${icon('headphones',30)}<h4>Repair question?</h4><p>If your phone needs attention, a structured repair request helps us understand the model and issue immediately.</p><a href="/repairs#booking" data-link class="link-arrow" style="margin-top:17px">Create repair request ${icon('arrow')}</a></div><div class="info-box">${icon('package',30)}<h4>Looking for a spare part?</h4><p>Tell us the exact brand and model; we'll need to confirm the correct variant and availability.</p><a href="/parts" data-link class="link-arrow" style="margin-top:17px">Explore parts ${icon('arrow')}</a></div><div class="info-box">${icon('info',30)}<h4>Prefer WhatsApp?</h4><p>${s.whatsapp?'Our WhatsApp contact is available through the link below.':'A WhatsApp number will appear when the business adds it to the site settings.'}</p>${s.whatsapp?`<a class="btn btn-dark btn-sm" style="margin-top:14px" target="_blank" rel="noopener noreferrer" href="https://wa.me/${esc(s.whatsapp.replace(/\D/g,''))}">Chat on WhatsApp ${icon('arrow',17)}</a>`:''}</div></aside></div></div></section>`,'/contact');}
function privacyPage(){frame(`${pageHero('Privacy notice','Your information. <span class="highlight">Your choice.</span>','How information submitted through this website is handled and how to contact the business about your records.')}<section class="section page-area"><div class="container" style="max-width:850px"><div class="form-panel"><div class="eyebrow">CUSTOMER INFORMATION</div><h2 style="font-size:2.8rem">Privacy notice</h2><p class="muted">This site is operated by ${esc(biz().business_name||'RepairlyLabs')} in ${esc(biz().city||'Varanasi')}. It collects information you choose to submit to communicate about repairs, spare-part requests, and questions.</p><h3>What we collect</h3><p>Name, mobile number, phone brand/model, details you submit about the device, locality or address where relevant, and optional contact details. A timestamp records your agreement to being contacted. The server also uses temporary IP-based request limits to reduce abuse.</p><h3>How the information is used</h3><p>To review your request, discuss options, arrange service or collection, manage part orders, and provide status updates. Records are saved in a database accessible to authorized team accounts. Online payment information is not collected by this website.</p><h3>Optional notifications</h3><p>The business may configure an external automation webhook for request notifications. If configured, the submitted details for that request may be sent to the business-selected notification provider. Ask the business which providers it uses.</p><h3>Retention and your choices</h3><p>Records are retained by the business until it deletes or archives them under its adopted retention policy. You can contact the operator to ask about your information, request correction, or discuss deletion subject to applicable recordkeeping requirements.</p><h3>Contact for privacy requests</h3><p>${esc(biz().privacy_contact||'Use the contact form to ask about your information.')}</p><a href="/contact" data-link class="btn btn-primary">Contact the team ${icon('arrow')}</a><p class="form-note">This is a starting privacy notice. The business owner must review it against actual operations and applicable law before going live.</p></div></div></section>`,'/privacy');}
function trackPage(){frame(`${pageHero('Track request','Know where things <span class="highlight">stand.</span>','Enter your request reference and the mobile number used at submission. No account needed.')}
 <section class="section page-area"><div class="container" style="max-width:850px"><form class="form-panel" data-form="track"><div class="pill">${icon('search',14)} REQUEST LOOKUP</div><h3 style="margin-top:18px">Find your request.</h3><p class="form-intro">Repair references start with RLM-. Part request references start with RLP-. Older references still work.</p><div class="form-grid"><div class="field"><label for="track-ref">Your reference ID *</label><input id="track-ref" name="ref" required maxlength="50" placeholder="e.g. RLM-261116-1A2B3C4D" style="text-transform:uppercase"></div><div class="field"><label for="track-phone">Mobile number *</label><input id="track-phone" name="phone" inputmode="tel" autocomplete="tel" required maxlength="17" placeholder="Number used for request"></div></div><button type="submit" class="btn btn-primary">Check status ${icon('arrow')}</button></form><div id="track-result"></div><p class="form-note" style="margin-top:21px">${icon('shield',17)} To protect customer information, both the reference and matching phone number are required.</p></div></section>`,'/track');}
function successScreen(ref,type,extra=''){return `<div class="success-card"><div class="success-icon">${icon('check',35)}</div><div class="pill">REQUEST RECEIVED</div><h2 style="font-size:2.45rem;margin:17px 0 10px">You're all set.</h2><p class="muted">Your ${type==='repair'?'repair':'spare part'} request has been saved. Keep this unique reference handy.</p><div class="reference">${esc(ref)}</div><div><button class="btn btn-ghost btn-sm" data-action="copy" data-value="${esc(ref)}">${icon('clipboard',17)} Copy reference</button></div><p class="muted" style="font-size:.82rem;margin:20px auto;max-width:400px">${extra||'The team will review your request. This is not a confirmed appointment or purchase.'}</p><div style="display:flex;justify-content:center;gap:11px;flex-wrap:wrap;margin-top:22px"><a href="/track" data-link class="btn btn-dark">Track request ${icon('arrow')}</a><a href="/" data-link class="btn btn-ghost">Back home</a></div></div>`;}
function renderTrack(data){const o=data.record;const isOrder=data.type==='order';const step=['pending','confirmed','in_progress','ready','completed'];const current=step.indexOf(o.status);return `<div class="form-panel" style="margin-top:25px"><div class="pill">${icon('checkcircle',15)} MATCH FOUND</div><div style="display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin:15px 0"><div><h3 style="margin:0">${isOrder?'Spare part request':'Repair request'}</h3><small class="muted">${esc(o.ref)} · Submitted ${esc(new Date(o.created_at+'Z').toLocaleDateString('en-IN'))}</small></div><span class="status-badge ${esc(o.status)}">${esc(o.status.replaceAll('_',' '))}</span></div><div class="line"></div><div class="status-timeline">${step.map((s,i)=>`<div class="status-line ${i<=current?'done':''}"><span class="status-dot"></span><div><strong>${s.replaceAll('_',' ')}</strong><small>${({pending:'Request received for review',confirmed:'Details reviewed and confirmed',in_progress:'Work is in progress',ready:'Ready for next step or collection',completed:'Request completed'})[s]}</small></div></div>`).join('')}${o.status==='cancelled'?`<div class="status-note">This request has been cancelled.</div>`:''}</div><div class="line" style="margin:24px 0"></div><h3 style="font-size:1.2rem">Request details</h3><p class="muted" style="font-size:.87rem">${isOrder?`${data.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join(' · ')}<br>Indicative parts subtotal: ${money(o.subtotal)} (exclusive of charges)`: `${esc(o.brand)} ${esc(o.model)} · ${esc(o.issue)}<br>Preference: ${esc(o.method)}${o.quote!==null?`<br>Recorded quote: ${money(o.quote)} (subject to confirmation)`:''}`}</p><a href="/contact" data-link class="link-arrow">Have a question? ${icon('arrow')}</a></div>`;}
function cartQty(){return state.cart.reduce((a,x)=>a+x.quantity,0);}
function updateCartCount(){const count=document.getElementById('cart-count');if(count){count.textContent=cartQty();count.hidden=!cartQty();}}
function addCart(id){const p=state.products.find(x=>x.id===id)||state.shopData?.items.find(x=>x.id===id);if(!p){toast('Part unavailable. Please refresh.',true);return;}if(p.stock<1){toast('This part is currently marked unavailable.',true);return;}const line=state.cart.find(x=>x.id===id);if(line){if(line.quantity>=Math.min(p.stock,20)){toast('Listed quantity limit reached.',true);return;}line.quantity++;}else {if(state.cart.length>=30){toast('Maximum 30 distinct parts per request.',true);return;}state.cart.push({id:p.id,quantity:1,product:p});}saved();updateCartCount();toast('Added to your part request cart.');}
function changeQty(id,delta){const item=state.cart.find(x=>x.id===id);if(!item)return;item.quantity+=delta;if(item.quantity>Math.min(item.product.stock,20)){item.quantity=Math.min(item.product.stock,20);toast('Listed quantity limit reached.',true);}if(item.quantity<=0)state.cart=state.cart.filter(x=>x.id!==id);saved();updateCartCount();openCart();}
function cartSubtotal(){return state.cart.reduce((s,i)=>s+i.product.price*i.quantity,0);}
function dialog(inner,cls=''){dialogRoot.innerHTML=`<div class="dialog-backdrop ${cls==='drawer'?'right':''}" data-action="backdrop"><div class="dialog ${cls}" role="dialog" aria-modal="true" aria-label="${cls==='drawer'?'Shopping cart':'Information'}">${inner}</div></div>`;document.body.classList.add('locked');const close=dialogRoot.querySelector('[data-action="close"]');close?.focus();}
function closeDialog(){dialogRoot.innerHTML='';document.body.classList.remove('locked');}
function openCart(checkout=false){if(checkout){checkoutDialog();return;}dialog(`<div class="dialog-head"><h3>Your part requests ${icon('shopping',20)}</h3><button class="icon-btn" data-action="close" aria-label="Close">${icon('x',21)}</button></div><div class="dialog-body">${state.cart.length?state.cart.map(i=>`<div class="cart-row"><div class="cart-mini">${icon(artIcons[i.product.image_kind]||'monitor',30)}</div><div><h4>${esc(i.product.name)}</h4><p>${esc(i.product.brand)} ${esc(i.product.model)}</p><strong>${money(i.product.price)}</strong></div><div class="qty-controls"><button aria-label="Decrease quantity" data-action="qty" data-id="${i.id}" data-delta="-1">−</button><b>${i.quantity}</b><button aria-label="Increase quantity" data-action="qty" data-id="${i.id}" data-delta="1">+</button></div></div>`).join(''):`<div class="empty-state">${icon('shopping',36)}<h3>Your cart is empty</h3><p>Explore parts and add the items you'd like the team to check.</p><a href="/parts" data-link class="btn btn-primary">Explore parts</a></div>`}</div>${state.cart.length?`<div class="cart-footer"><div class="cart-total"><span>Indicative parts subtotal</span><strong>${money(cartSubtotal())}</strong></div><p class="mini-muted">All sample prices and stock are illustrative. Final price, fit and availability confirmed separately. No payment online.</p><button class="btn btn-primary" data-action="checkout">Continue to request ${icon('arrow')}</button></div>`:''}`,'drawer');}
function checkoutDialog(){if(!state.cart.length)return openCart();dialog(`<div class="dialog-head"><h3>Request your spare parts</h3><button class="icon-btn" data-action="close" aria-label="Close">${icon('x',21)}</button></div><div class="dialog-body"><p class="form-intro">No payment will be taken. The team verifies stock, exact model compatibility, pricing and any delivery charges before confirming.</p><div class="status-note" style="margin-bottom:22px">${icon('info',18)} ${state.cart.length} item(s) · Indicative subtotal ${money(cartSubtotal())} (not final)</div><form data-form="checkout"><div class="form-grid"><div class="field"><label>Your full name *</label><input name="name" autocomplete="name" maxlength="100" required></div><div class="field"><label>Mobile number *</label><input name="phone" autocomplete="tel" inputmode="tel" maxlength="17" required></div><div class="field"><label>Your area *</label>${areaInput()}</div><div class="field"><label>How to receive parts *</label><select name="mode" id="checkout-mode"><option value="Discuss collection options">Discuss collection options</option>${biz().address?'<option value="Workshop collection">Workshop collection (after confirmation)</option>':''}${biz().delivery_enabled==='1'?'<option value="Request delivery">Request delivery (subject to confirmation)</option>':''}</select></div><div class="field span2"><label>Delivery address / landmark (if applicable)</label><input name="address" autocomplete="street-address" maxlength="350" placeholder="Required for delivery"></div><div class="field span2"><label>Additional requirements</label><textarea name="notes" maxlength="800" placeholder="Exact phone variant, part grade preference or questions"></textarea></div>${consentField()}</div><button class="btn btn-primary" type="submit" style="width:100%">Submit parts request ${icon('arrow')}</button></form></div>`,'wide');}
async function showDetail(id){try{const p=await api(`/api/products/${id}`);dialog(`<div class="dialog-head"><h3>Spare part details</h3><button class="icon-btn" data-action="close" aria-label="Close">${icon('x',21)}</button></div><div class="dialog-body detail-top">${productArt(p)}<div class="detail-info"><span class="pill">${esc(p.category)}</span><h2>${esc(p.name)}</h2><p>Illustrated part listing for a device model. Fit depends on the precise model variant and component specification.</p><div class="spec-row"><span>Brand</span><b>${esc(p.brand)}</b></div><div class="spec-row"><span>Listed model</span><b>${esc(p.model)}</b></div><div class="spec-row"><span>Component grade</span><b>${esc(p.grade)}</b></div><div class="spec-row"><span>Reference SKU</span><b>${esc(p.sku)}</b></div><div class="spec-row"><span>Listed stock</span><b>${p.sample?'Example quantity':String(p.stock)}</b></div><div style="margin-top:22px"><div class="price">${money(p.price)} <small>${p.sample?'Example price; confirm before ordering':'Listed price; confirm before ordering'}</small></div></div><button class="btn btn-primary" data-action="add" data-id="${p.id}">Add to request ${icon('plus')}</button><p class="mini-muted" style="margin-top:16px">${esc(p.description||'Final compatibility is confirmed with the team.')}</p></div></div>`,'wide');}catch(e){toast(e.message,true);}}
/* Admin console */
const adminTabs=[['overview','dashboard','Overview'],['bookings','calendar','Repair requests'],['orders','shopping','Parts orders'],['products','package','Inventory'],['services','repair','Services'],['messages','message','Messages'],['models','phone','Phone models'],['settings','settings','Site settings'],['security','shield','Security']];
let recoveryToken='';
async function adminRoute(){const m=location.hash.match(/^#recover=([A-Za-z0-9_-]{43})$/);if(m){recoveryToken=m[1];history.replaceState(null,'',location.pathname+location.search);state.admin=null;renderRecovery();return;}try{state.admin=await api('/api/admin/me');renderAdmin();}catch{state.admin=null;renderLogin();}}
function passwordField(name,label,autocomplete='new-password',min=8){return `<div class="field"><label for="access-${name}">${label}</label><div class="access-password"><input id="access-${name}" name="${name}" type="password" autocomplete="${autocomplete}" minlength="${min}" maxlength="150" required><button type="button" class="access-toggle" data-access-toggle="access-${name}" aria-label="Show password">Show</button></div></div>`;}
function renderLogin(){document.title='Team sign in | RepairlyLabs';app.innerHTML=`<div class="admin-login access-login"><form class="login-card" data-form="admin-login">${logo()}<div class="pill">TEAM ACCESS</div><h1 style="margin-top:17px">Welcome back.</h1><p class="muted" style="font-size:.87rem;margin-bottom:28px">Sign in to manage repair requests, part orders and your storefront.</p><div class="field"><label for="login-username">Email or username</label><input id="login-username" name="username" autocomplete="username" required maxlength="120" placeholder="owner or your registered email" autocapitalize="none" spellcheck="false"></div>${passwordField('password','Password','current-password',1)}<div id="access-error" role="alert" class="access-error" hidden></div><button class="btn btn-primary" type="submit" style="width:100%">Sign in ${icon('arrow')}</button><button type="button" class="access-help" data-access-help>Forgot password / first-time setup?</button><div id="access-help" class="status-note" hidden>Owner: on your trusted server computer, ask your trusted local coding agent to run <strong>scripts/agent-owner-recovery.mjs</strong> and open its private 15-minute link. No launcher is required. Team members: ask the owner to reset your password in Security. There is no public admin registration.</div><a href="/" data-link style="display:block;text-align:center;margin-top:24px;color:var(--slate);font-size:.83rem">${icon('arrow',16)} Back to website</a></form></div>`;}
function renderRecovery(){document.title='Owner recovery | RepairlyLabs';app.innerHTML=`<div class="admin-login access-login"><form class="login-card" data-form="admin-recovery">${logo()}<div class="pill">PRIVATE OWNER ACCESS</div><h1 style="margin-top:17px">Set your password.</h1><p class="muted">This one-time link expires after 15 minutes. Your bookings, orders and existing owner username stay intact.</p><div class="field"><label for="recovery-email">Login email (optional)</label><input id="recovery-email" type="email" name="email" autocomplete="email" maxlength="120" placeholder="you@example.com"><small>Leave blank to retain any existing email. For a new account, the default username is owner.</small></div>${passwordField('password','New password (8+ characters)')}${passwordField('confirm','Confirm new password')}<div id="access-error" class="access-error" role="alert" hidden></div><button class="btn btn-primary" type="submit" style="width:100%">Save owner access ${icon('arrow')}</button><a href="/admin" data-link class="access-help">Cancel and sign in</a></form></div>`;}
function adminShell(){app.innerHTML=`<div class="admin-shell"><aside class="admin-sidebar">${logo()}<div class="admin-subtitle">Operations console</div><nav class="admin-nav">${adminTabs.map(([tab,ico,label])=>`<button data-admin-tab="${tab}" class="${state.adminTab===tab?'active':''}">${icon(ico,19)} ${label}</button>`).join('')}</nav><div class="admin-bottom"><a href="/" data-link class="btn btn-outline btn-sm">${icon('eye',16)} View storefront</a><button class="btn btn-ghost btn-sm" data-action="admin-logout">${icon('logout',16)} Log out</button></div></aside><div class="admin-main"><div class="admin-top"><div><h1 id="admin-heading">Overview</h1><p id="admin-subheading">Your mobile care operation, all in one place.</p></div><div style="display:flex;align-items:center;gap:12px"><span class="muted" style="font-size:.84rem">${esc(state.admin.username)}</span><span class="avatar">${esc(state.admin.username[0].toUpperCase())}</span></div></div><div id="admin-content"></div><div class="admin-mobile-nav" style="margin-top:36px"><button class="btn btn-ghost btn-sm" data-action="admin-logout">${icon('logout',16)} Log out</button></div></div></div>`;}
async function renderAdmin(){document.title='Operations Console | RepairlyLabs';adminShell();const link=document.createElement('a');link.href='/repair-center/index.html?admin=1';link.textContent='Open Repair Desk →';link.className='btn btn-primary';link.style.cssText='position:fixed;bottom:20px;right:20px;z-index:1000';link.id='repair-center-link';document.getElementById(link.id)?.remove();document.querySelector('.admin-main')?.append(link);await loadAdminTab();}
async function loadAdminTab(){const tab=state.adminTab;const names={overview:'Overview',bookings:'Repair requests',orders:'Parts orders',products:'Part inventory',services:'Repair services',messages:'Messages',models:'Phone models',settings:'Site settings',security:'Account security'};const heading=document.getElementById('admin-heading'),content=document.getElementById('admin-content');if(!content)return;heading.textContent=names[tab];document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===tab));content.innerHTML='<div class="muted" style="padding:55px;text-align:center">Loading…</div>';try{
 let data;
 switch(tab){case 'overview':data=await api('/api/admin/overview');break;case 'bookings':data=await api('/api/admin/bookings');break;case 'orders':data=await api('/api/admin/orders');break;case 'products':data=await api('/api/admin/products?limit=100');break;case 'services':data=await api('/api/admin/services');break;case 'messages':data=await api('/api/admin/contacts');break;case 'models':data=await api('/api/admin/models');break;case 'settings':data=await api('/api/admin/settings');break;case 'security':data=state.admin.role==='owner'?await api('/api/admin/team'):[];break;}
 state.adminData=data;const views={overview:overviewView,bookings:bookingAdminView,orders:ordersAdminView,products:productsAdminView,services:servicesAdminView,messages:messagesAdminView,models:modelsAdminView,settings:settingsAdminView,security:securityAdminView};content.innerHTML=views[tab](data);}
 catch(e){content.innerHTML=`<div class="status-note">${esc(e.message)}</div>`;}}
function metric(label,n,ico){return `<div class="metric"><div class="metric-icon">${icon(ico,23)}</div><div class="num">${n}</div><div class="lbl">${esc(label)}</div></div>`;}
function badge(s){return `<span class="status-badge ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`;}
function overviewView(d){const mini=(items,type)=>`<div class="admin-panel"><h3>${type==='booking'?'Recent repairs':'Recent parts orders'}</h3>${items.length?items.map(o=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 0;border-bottom:1px solid var(--line)"><div><strong style="font-size:.87rem">${esc(o.name)}</strong><div class="muted" style="font-size:.72rem">${esc(o.ref)} · ${type==='booking'?esc(o.model):money(o.subtotal)}</div></div>${badge(o.status)}</div>`).join(''):'<p class="muted">Nothing to show yet.</p>'}<button class="link-arrow" data-admin-tab="${type==='booking'?'bookings':'orders'}" style="margin-top:21px;background:none">View all ${icon('arrow',17)}</button></div>`;return `<div class="metric-grid">${metric('Repair requests',d.bookings,'repair')}${metric('Awaiting repair review',d.pendingBookings,'clock')}${metric('Parts requests',d.orders,'shopping')}${metric('Awaiting order review',d.pendingOrders,'package')}</div><div class="metric-grid" style="margin-top:17px">${metric('Active parts',d.listedParts,'package')}${metric('Low stock (≤3)',d.lowStock,'info')}${metric('Unread messages',d.unreadMessages,'message')}${metric('Team dashboard',1,'dashboard')}</div><div class="admin-panels">${mini(d.recentBookings,'booking')}${mini(d.recentOrders,'order')}</div><div class="status-note" style="margin-top:24px">${icon('info',18)} Example catalog entries are flagged as samples. Before public launch, update your real stock, prices, business contact details, service options, and warranty policy in this console.</div>`;}
const allStatuses=['pending','confirmed','in_progress','ready','completed','cancelled'];
function statusSelect(current,kind){const choices=kind==='order'?{pending:['pending','confirmed','cancelled'],confirmed:['confirmed','in_progress','ready','cancelled'],in_progress:['in_progress','ready','cancelled'],ready:['ready','completed','cancelled'],completed:['completed'],cancelled:['cancelled']}[current]||[current]:allStatuses;return `<select class="admin-row-status" aria-label="Update status">${choices.map(c=>`<option ${c===current?'selected':''} value="${c}">${c.replaceAll('_',' ')}</option>`).join('')}</select>`;}
function bookingAdminView(list){return `<div class="admin-toolbar"><p class="muted">${list.length} latest repair requests · Confirm dates and quotes outside the form.</p><button data-export="bookings" class="btn btn-ghost btn-sm">${icon('download',17)} Export CSV</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Ref / customer</th><th>Phone / model</th><th>Issue / preference</th><th>Area & date</th><th>Update status</th><th>Quote ₹ / note</th><th>Action</th></tr></thead><tbody>${list.map(b=>`<tr data-record-row="booking"><td><strong>${esc(b.ref)}</strong><br>${esc(b.name)}<br><span class="muted">${esc(b.created_at)}</span></td><td>${esc(b.phone)}<br>${esc(b.brand)} ${esc(b.model)}</td><td>${esc(b.issue)}<br><span class="muted">${esc(b.method)}</span>${b.notes?`<br><span class="muted">${esc(b.notes)}</span>`:''}</td><td>${esc(b.locality)}<br>${esc(b.date||'No date requested')}${b.address?`<br><span class="muted">${esc(b.address)}</span>`:''}</td><td>${badge(b.status)}<div style="margin-top:8px">${statusSelect(b.status,'booking')}</div></td><td><input class="admin-row-quote" type="number" min="0" placeholder="No quote" value="${b.quote??''}" style="width:110px"><br><input class="admin-row-note" placeholder="Internal note" value="${esc(b.admin_note)}" maxlength="800" style="margin-top:6px;width:145px"></td><td><button class="btn btn-dark btn-sm" data-admin-save="booking" data-id="${b.id}">Save</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="empty-state">No requests yet.</div>'}`;}
function ordersAdminView(list){return `<div class="admin-toolbar"><p class="muted">${list.length} latest part requests · Stock is deducted only when confirming a pending order.</p><button data-export="orders" class="btn btn-ghost btn-sm">${icon('download',17)} Export CSV</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Ref / customer</th><th>Phone / fulfillment</th><th>Parts requested</th><th>Listed total</th><th>Status</th><th>Note / action</th></tr></thead><tbody>${list.map(o=>`<tr data-record-row="order"><td><strong>${esc(o.ref)}</strong><br>${esc(o.name)}<br><span class="muted">${esc(o.created_at)}</span></td><td>${esc(o.phone)}<br>${esc(o.mode)}<br>${esc(o.locality)}<br><span class="muted">${esc(o.address)}</span></td><td>${o.items.map(i=>`<div>${esc(i.name)} × ${i.quantity}${i.sample?' <span class="pill" style="padding:3px 6px">Sample</span>':''}</div>`).join('')}<span class="muted">${esc(o.notes)}</span></td><td><strong>${money(o.subtotal)}</strong><br><span class="muted">Excludes other charges</span></td><td>${badge(o.status)}<div style="margin-top:8px">${statusSelect(o.status,'order')}</div></td><td><input class="admin-row-note" placeholder="Internal note" value="${esc(o.admin_note)}" maxlength="800"><br><button class="btn btn-dark btn-sm" style="margin-top:7px" data-admin-save="order" data-id="${o.id}">Save status</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':'<div class="empty-state">No orders yet.</div>'}`;}
function productsAdminView(d){return `<div class="admin-toolbar"><p class="muted">${d.total} listed products · Current page shows ${d.items.length}.</p><div style="display:flex;gap:10px"><button data-export="products" class="btn btn-ghost btn-sm">${icon('download',16)} CSV</button><button data-action="new-product" class="btn btn-primary btn-sm">${icon('plus',16)} Add part</button></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>SKU / product</th><th>Device</th><th>Category</th><th>Price</th><th>Stock</th><th>Catalog state</th><th>Edit</th></tr></thead><tbody>${d.items.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><span class="muted">${esc(p.sku)}</span></td><td>${esc(p.brand)}<br>${esc(p.model)}</td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td>${p.active?'Active':'Hidden'}${p.sample?'<br><span class="pill">DEMO</span>':''}</td><td><button class="btn btn-ghost btn-sm" data-edit-product="${p.id}">${icon('edit',16)} Edit</button></td></tr>`).join('')}</tbody></table></div>${d.total>d.items.length?`<div style="margin-top:22px"><button class="btn btn-ghost" data-action="more-admin-products">Load more</button></div>`:''}<div class="status-note" style="margin-top:22px">Set “Sample listing” to OFF only after verifying the real part, device variant, selling price, available quantity and warranty terms.</div>`;}
function servicesAdminView(d){return `<div class="admin-toolbar"><p class="muted">Update cards and descriptions displayed on the website.</p><button class="btn btn-primary btn-sm" data-action="new-service">${icon('plus',16)} New service</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Service</th><th>Description</th><th>Visibility</th><th>Order</th><th>Edit</th></tr></thead><tbody>${d.map(s=>`<tr><td><strong>${esc(s.title)}</strong><br><span class="muted">${esc(s.slug)}</span></td><td>${esc(s.description)}</td><td>${s.active?'Visible':'Hidden'}</td><td>${s.sort_order}</td><td><button class="btn btn-ghost btn-sm" data-edit-service="${s.id}">${icon('edit',16)} Edit</button></td></tr>`).join('')}</tbody></table></div>`;}
function messagesAdminView(d){return `<div class="admin-toolbar"><p class="muted">${d.length} latest messages. Read status helps track follow-ups.</p><button data-export="contacts" class="btn btn-ghost btn-sm">${icon('download',16)} Export</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Customer</th><th>Message</th><th>Received</th><th>Read status</th></tr></thead><tbody>${d.map(m=>`<tr><td><strong>${esc(m.name)}</strong><br>${esc(m.phone)}<br>${esc(m.email)}</td><td style="min-width:230px;white-space:pre-wrap">${esc(m.message)}</td><td>${esc(m.created_at)}</td><td><button data-admin-read="${m.id}" data-read="${m.read?0:1}" class="btn btn-ghost btn-sm">${m.read?'Mark unread':'Mark read'}</button><button class="btn btn-ghost btn-sm" data-admin-delete-contact="${m.id}" style="margin:4px">${icon('trash',15)}</button></td></tr>`).join('')}</tbody></table></div>${d.length?'':'<div class="empty-state">No messages yet.</div>'}`;}
function modelsAdminView(d){return `<div class="admin-panels" style="margin-top:0"><div class="admin-panel"><h3>Device model catalog</h3><div class="metric" style="background:#f6f8fa"><div class="num">${d.length}</div><div class="lbl">Models in the catalog</div></div><p class="muted" style="font-size:.87rem;margin-top:17px">Users can also type a model that isn't listed. Use this importer to add models and brands as they arrive in India.</p><p class="muted" style="font-size:.8rem">Formats: one <strong>Brand, Model</strong> per line. Duplicates are skipped.</p></div><div class="admin-panel"><h3>Import models</h3><form data-form="admin-models"><div class="field"><label>Brand, Model (one per line)</label><textarea name="lines" rows="9" required placeholder="Samsung, Galaxy S25 Ultra&#10;Apple, iPhone 16&#10;OnePlus, OnePlus 13"></textarea></div><button class="btn btn-primary" type="submit">${icon('plus',18)} Import device models</button></form></div></div><div class="admin-panel" style="margin-top:24px"><h3>Current brands</h3><div style="display:flex;flex-wrap:wrap;gap:10px">${[...new Set(d.map(x=>x.brand))].map(b=>`<span class="chip">${esc(b)}</span>`).join('')}</div></div>`;}
function settingsAdminView(d){const fields=[['business_name','Public business name','text'],['tagline','Short tagline','text'],['city','Service city','text'],['phone','Customer phone','tel'],['whatsapp','WhatsApp number incl. country code','tel'],['email','Support email','email'],['address','Actual workshop address / service area','text'],['hours','Working hours (write actual hours)','text'],['instagram','Instagram page (optional)','url'],['map_url','Google Maps share link (optional)','url'],['privacy_contact','Contact for privacy or data deletion requests','text'],['announcement','Homepage announcement','text'],['terms','Service terms (customer-facing)','textarea'],['warranty','Warranty policy (customer-facing)','textarea']];return `<div class="admin-panel settings-panel"><h3>Your business details</h3><p class="muted" style="font-size:.85rem">These details appear publicly. Do not enter example numbers or an address that customers cannot visit.</p><form data-form="admin-settings"><div class="form-grid">${fields.map(([id,label,type])=>`<div class="field ${type==='textarea'?'span2':''}"><label for="set-${id}">${label}</label>${type==='textarea'?`<textarea id="set-${id}" name="${id}" maxlength="1500">${esc(d[id])}</textarea>`:`<input id="set-${id}" name="${id}" type="${type}" value="${esc(d[id])}" maxlength="350">`}</div>`).join('')}<div class="field"><label>Pickup requests</label><select name="pickup_enabled"><option value="1" ${d.pickup_enabled==='1'?'selected':''}>Accept pickup requests</option><option value="0" ${d.pickup_enabled!=='1'?'selected':''}>Disabled</option></select></div><div class="field"><label>Parts delivery requests</label><select name="delivery_enabled"><option value="0" ${d.delivery_enabled!=='1'?'selected':''}>Disabled</option><option value="1" ${d.delivery_enabled==='1'?'selected':''}>Allow delivery requests</option></select></div></div><button class="btn btn-primary" type="submit">${icon('save',18)} Save public settings</button></form></div>`;}
function securityAdminView(accounts=[]){const team=accounts.filter(a=>a.role==='team');return `<div class="admin-panel" style="max-width:720px"><h3>Your login details</h3><p class="muted">Signed in as ${esc(state.admin.username)} · ${esc(state.admin.role)}. Email is a login alias, not a verified recovery address.</p><form data-form="admin-email"><div class="field"><label>Login email (optional)</label><input type="email" name="email" maxlength="120" value="${esc(state.admin.email)}" placeholder="you@example.com"></div><div class="field"><label>Current password</label><input type="password" name="current" autocomplete="current-password" required></div><button class="btn btn-primary" type="submit">Save login email</button></form></div><div class="admin-panel" style="max-width:720px;margin-top:20px"><h3>Change your password</h3><p class="muted">Use a unique password of at least 8 characters. Other sessions will be signed out.</p><form data-form="admin-password"><div class="field"><label>Current password</label><input type="password" name="current" autocomplete="current-password" required></div><div class="field"><label>New password (8+ characters)</label><input type="password" name="next" minlength="8" maxlength="150" autocomplete="new-password" required></div><button class="btn btn-primary" type="submit">Change password</button></form></div>${state.admin.role==='owner'?`<div class="admin-panel" style="max-width:720px;margin-top:20px"><h3>Team accounts</h3><p class="muted">Team members can manage business operations. Only the owner can create, reset, enable or disable team accounts.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Account</th><th>Email</th><th>Access</th></tr></thead><tbody>${accounts.map(a=>`<tr><td>${esc(a.username)}</td><td>${esc(a.email||'—')}</td><td>${a.disabled?'Disabled':esc(a.role)}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:22px">Create team account</h3><form data-form="admin-team-create"><div class="field"><label>Team email or username</label><input name="username" required maxlength="120" autocomplete="off"></div><div class="field"><label>Initial password (8+ characters)</label><input name="password" type="password" minlength="8" maxlength="150" autocomplete="new-password" required></div><div class="field"><label>Your owner password</label><input name="current" type="password" autocomplete="current-password" required></div><button class="btn btn-primary" type="submit">Create account</button></form>${team.length?`<h3 style="margin-top:22px">Manage existing team account</h3><form data-form="admin-team-manage"><div class="field"><label>Team account</label><select name="username">${team.map(a=>`<option value="${esc(a.username)}">${esc(a.username)}${a.disabled?' (disabled)':''}</option>`).join('')}</select></div><div class="field"><label>Action</label><select name="action"><option value="reset">Reset password</option><option value="disable">Disable access</option><option value="enable">Enable access</option></select></div><div class="field"><label>New password (only for reset)</label><input name="password" type="password" maxlength="150" autocomplete="new-password"></div><div class="field"><label>Your owner password</label><input name="current" type="password" autocomplete="current-password" required></div><button class="btn btn-primary" type="submit">Apply account change</button></form>`:''}</div>`:''}<div class="status-note" style="max-width:720px;margin-top:23px">${icon('info',17)} Forgot the owner password? Use the private recovery launcher on the server computer. No public password reset or self-registration is enabled.</div>`;}

function productModal(id){const p=state.adminData?.items?.find(x=>x.id===id)||{};const isNew=!id;const fields=[['sku','Stock keeping unit *',p.sku||''],['name','Part title *',p.name||''],['brand','Brand *',p.brand||''],['model','Exact model / variant *',p.model||''],['grade','Part grade',p.grade||'Ask for details'],['price','Price in INR *',p.price??0,'number'],['stock','Available quantity *',p.stock??0,'number']];dialog(`<div class="dialog-head"><h3>${isNew?'Add a spare part':'Edit spare part'}</h3><button class="icon-btn" data-action="close">${icon('x')}</button></div><div class="dialog-body"><form data-form="admin-product" data-id="${id||''}"><div class="form-grid">${fields.map(([name,label,value,type='text'])=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" ${type==='number'?'min="0"':''} required value="${esc(value)}" maxlength="${type==='text'?150:undefined}"></div>`).join('')}<div class="field"><label>Part category</label><select name="category">${state.config.categories.map(c=>`<option ${p.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Image illustration type</label><select name="image_kind">${['display','battery','port','panel','camera','speaker','flex'].map(c=>`<option value="${c}" ${p.image_kind===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Listing visible?</label><select name="active"><option value="1" ${p.active!==false?'selected':''}>Visible</option><option value="0" ${p.active===false?'selected':''}>Hidden</option></select></div><div class="field"><label>Show on homepage?</label><select name="featured"><option value="0" ${!p.featured?'selected':''}>No</option><option value="1" ${p.featured?'selected':''}>Yes</option></select></div><div class="field"><label>Sample listing?</label><select name="sample"><option value="1" ${p.sample!==false?'selected':''}>Yes — indicative / demo</option><option value="0" ${p.sample===false?'selected':''}>No — verified live listing</option></select></div><div class="field span2"><label>Description and fit notes</label><textarea name="description" maxlength="900">${esc(p.description||'Exact device variant and compatibility must be verified before confirmation.')}</textarea></div></div><button class="btn btn-primary" type="submit">${icon('save',18)} Save part</button></form></div>`,'wide');}
function serviceModal(id){const s=state.adminData?.find(x=>x.id===id)||{};dialog(`<div class="dialog-head"><h3>${id?'Edit repair service':'Add repair service'}</h3><button class="icon-btn" data-action="close">${icon('x')}</button></div><div class="dialog-body"><form data-form="admin-service"><input type="hidden" name="id" value="${id||''}"><div class="form-grid"><div class="field"><label>Slug</label><input name="slug" required value="${esc(s.slug||'')}" placeholder="speaker-repair"></div><div class="field"><label>Title</label><input name="title" required value="${esc(s.title||'')}"></div><div class="field"><label>Icon name</label><select name="icon">${['monitor-smartphone','battery-charging','plug-zap','droplets','camera','volume-2','settings-2','layers-3','wrench'].map(i=>`<option value="${i}" ${s.icon===i?'selected':''}>${i}</option>`).join('')}</select></div><div class="field"><label>Highlight label</label><input name="tag" value="${esc(s.tag||'')}"></div><div class="field"><label>Visible?</label><select name="active"><option value="1" ${s.active!==0?'selected':''}>Yes</option><option value="0" ${s.active===0?'selected':''}>No</option></select></div><div class="field"><label>Display order</label><input name="sort_order" type="number" min="0" value="${s.sort_order??9}"></div><div class="field span2"><label>Service description</label><textarea name="description" required maxlength="400">${esc(s.description||'')}</textarea></div></div><button class="btn btn-primary" type="submit">${icon('save',18)} Save service</button></form></div>`,'wide');}
/* App actions and event delegation */
async function route(){closeDialog();const path=location.pathname;window.scrollTo({top:0,behavior:'instant'});switch(path){case '/':home();break;case '/repairs':repairs();break;case '/parts':parts();break;case '/about':about();break;case '/contact':contact();break;case '/track':trackPage();break;case '/privacy':privacyPage();break;case '/admin':await adminRoute();break;default:frame(`<div class="not-found"><div><h1>404</h1><h3>This page took a wrong turn.</h3><a class="btn btn-primary" href="/" data-link>Back to RepairlyLabs ${icon('arrow')}</a></div></div>`,path);}if(location.hash)setTimeout(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView({behavior:'smooth',block:'start'}),90);}
function navigate(url){const target=new URL(url,location.origin);if(target.origin!==location.origin){window.location.href=url;return;}history.pushState({},'',target.pathname+target.search+target.hash);route();}
function updateNavbar(){document.getElementById('navbar')?.classList.toggle('scrolled',scrollY>18);}
function bindReveal(){if(!('IntersectionObserver'in window)){document.querySelectorAll('.reveal').forEach(n=>n.classList.add('visible'));return;}const ob=new IntersectionObserver(items=>{for(const e of items)if(e.isIntersecting){e.target.classList.add('visible');ob.unobserve(e.target);}},{threshold:.08,rootMargin:'0px 0px -25px 0px'});document.querySelectorAll('.reveal').forEach(el=>ob.observe(el));}
async function handleAdminSave(btn){const type=btn.dataset.adminSave,id=Number(btn.dataset.id),row=btn.closest('[data-record-row]');const status=row.querySelector('.admin-row-status')?.value,admin_note=row.querySelector('.admin-row-note')?.value||'';const quote=row.querySelector('.admin-row-quote')?.value??'';loadingButton(btn,true);try{await api(`/api/admin/${type==='booking'?'bookings':'orders'}/${id}`,{method:'PATCH',body:type==='booking'?{status,admin_note,quote}:{status,admin_note}});toast('Status saved successfully.');await loadAdminTab();}catch(e){toast(e.message,true);loadingButton(btn,false);}}
async function handleExport(type){try{const response=await fetch('/api/admin/export?type='+encodeURIComponent(type));if(!response.ok)throw new Error('Export unavailable.');const blob=await response.blob();const href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`repairlylabs-${type}-${dateLocal()}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),2000);}catch(e){toast(e.message,true);}}
document.addEventListener('click',async event=>{
 const nav=event.target.closest('a[data-link]');if(nav){event.preventDefault();navigate(nav.getAttribute('href'));return;}
 const category=event.target.closest('[data-category]');if(category){state.shop.category=category.dataset.category;state.shop.limit=24;document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el===category));loadShop();return;}
 const tab=event.target.closest('[data-admin-tab]');if(tab){state.adminTab=tab.dataset.adminTab;await loadAdminTab();return;}
 const exportBtn=event.target.closest('[data-export]');if(exportBtn){await handleExport(exportBtn.dataset.export);return;}
 const save=event.target.closest('[data-admin-save]');if(save){await handleAdminSave(save);return;}
 const editPart=event.target.closest('[data-edit-product]');if(editPart){productModal(Number(editPart.dataset.editProduct));return;}
 const editService=event.target.closest('[data-edit-service]');if(editService){serviceModal(Number(editService.dataset.editService));return;}
 const del=event.target.closest('[data-admin-delete-contact]');if(del){if(confirm('Permanently delete this contact message?')){try{await api('/api/admin/contacts/'+del.dataset.adminDeleteContact,{method:'DELETE'});toast('Contact deleted.');loadAdminTab();}catch(e){toast(e.message,true);}}return;}
 const read=event.target.closest('[data-admin-read]');if(read){try{await api(`/api/admin/contacts/${read.dataset.adminRead}`,{method:'PATCH',body:{read:read.dataset.read==='1'}});toast('Message status updated.');loadAdminTab();}catch(e){toast(e.message,true);}return;}
 const action=event.target.closest('[data-action]');if(!action)return;const what=action.dataset.action;
 if(what==='backdrop'){if(event.target===action)closeDialog();return;}
 if(what==='close'){closeDialog();return;}
 if(what==='retry'){location.reload();return;}
 if(what==='menu'){const menu=document.getElementById('mobile-nav');menu?.classList.toggle('hide');action.setAttribute('aria-expanded',String(!menu?.classList.contains('hide')));return;}
 if(what==='cart'){openCart();return;}
 if(what==='add'){addCart(Number(action.dataset.id));return;}
 if(what==='detail'){showDetail(Number(action.dataset.id));return;}
 if(what==='qty'){changeQty(Number(action.dataset.id),Number(action.dataset.delta));return;}
 if(what==='checkout'){checkoutDialog();return;}
 if(what==='copy'){try{await navigator.clipboard.writeText(action.dataset.value);toast('Reference copied.');}catch{toast('Select the reference above to copy it.');}return;}
 if(what==='clear-filters'){state.shop={brand:'',category:'',q:'',model:'',limit:24};document.getElementById('shop-brand').value='';document.getElementById('shop-search').value='';document.getElementById('shop-model').value='';document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',!el.dataset.category));loadShop();return;}
 if(what==='more-parts'){await loadShop(true);return;}
 if(what==='new-product'){productModal(null);return;}
 if(what==='new-service'){serviceModal(null);return;}
 if(what==='more-admin-products'){try{const next=await api('/api/admin/products?limit=100&offset='+state.adminData.items.length);state.adminData.items.push(...next.items);document.getElementById('admin-content').innerHTML=productsAdminView(state.adminData);}catch(e){toast(e.message,true);}return;}
 if(what==='admin-logout'){try{await api('/api/admin/logout',{method:'POST',body:{}});}catch{}state.admin=null;navigate('/');toast('Signed out.');}
});
let searchTimer;
document.addEventListener('input',event=>{const el=event.target;
 if(el.id==='shop-search'||el.id==='shop-model'){const key=el.id==='shop-search'?'q':'model';state.shop[key]=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadShop(),270);}
});
document.addEventListener('change',async event=>{if(event.target.id==='shop-brand'){state.shop.brand=event.target.value;state.shop.limit=24;loadShop();}
 if(event.target.id==='brand'&&document.getElementById('model-options')){const brand=event.target.value;const list=document.getElementById('model-options');document.getElementById('model').value='';list.innerHTML='';if(brand&&brand!=='Other'){try{const models=await api('/api/models?brand='+encodeURIComponent(brand));if(document.getElementById('brand')?.value===brand)list.innerHTML=models.map(m=>`<option value="${esc(m.model)}"></option>`).join('');}catch{}}}
});
document.addEventListener('click',event=>{const t=event.target.closest('[data-access-toggle]');if(t){const i=document.getElementById(t.dataset.accessToggle);if(i){i.type=i.type==='password'?'text':'password';t.textContent=i.type==='password'?'Show':'Hide';t.setAttribute('aria-label',t.textContent+' password');}}if(event.target.closest('[data-access-help]')){const h=document.getElementById('access-help');if(h)h.hidden=!h.hidden;}});
document.addEventListener('submit',async event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();const type=f.dataset.form;const b=Object.fromEntries(new FormData(f).entries()),button=f.querySelector('button[type="submit"]');loadingButton(button,true);try{
 switch(type){
 case 'booking':{const d=await api('/api/bookings',{method:'POST',body:b});f.parentElement.innerHTML=successScreen(d.ref,'repair')+(d.repair_access?'<div class="form-panel" style="margin-top:20px"><h3>Your private repair access</h3><p>Save this link and access code now. You will use them to approve charges and pay securely.</p><p style="overflow-wrap:anywhere"><code>'+esc(d.repair_access)+'</code></p><a class="btn btn-primary" href="/repair-center/index.html#'+encodeURIComponent(d.ref)+':'+encodeURIComponent(d.repair_access)+'">Open secure repair portal</a></div>':'');toast('Repair request saved.');break;}
 case 'contact':{await api('/api/contact',{method:'POST',body:b});f.innerHTML=`<div class="success-icon">${icon('check',32)}</div><h3>Message received.</h3><p class="muted">Your message has been saved for the team. Thank you for getting in touch.</p><a href="/" data-link class="btn btn-dark">Back home ${icon('arrow')}</a>`;toast('Message sent to the team dashboard.');break;}
 case 'track':{const data=await api('/api/track?'+new URLSearchParams({ref:b.ref.toUpperCase(),phone:b.phone}));document.getElementById('track-result').innerHTML=renderTrack(data)+(data.type==='repair'?'<p style="margin-top:15px"><a class="btn btn-primary" href="/repair-center/?ref='+encodeURIComponent(data.record.ref)+'">Open quotation & payment portal</a></p>':'');break;}
 case 'checkout':{const d=await api('/api/orders',{method:'POST',body:{...b,items:state.cart.map(x=>({id:x.id,quantity:x.quantity}))}});state.cart=[];saved();updateCartCount();closeDialog();document.querySelector('main')?.insertAdjacentHTML('afterbegin',`<section class="section page-area"><div class="container">${successScreen(d.ref,'parts','The team will verify exact device fit, price, stock and collection or delivery arrangements before confirming. No payment was taken.')}</div></section>`);window.scrollTo({top:0,behavior:'smooth'});toast('Parts request saved.');break;}
 case 'admin-recovery':{if(b.password!==b.confirm)throw Error('Passwords do not match.');const d=await api('/api/admin/recover',{method:'POST',body:{token:recoveryToken,password:b.password,email:b.email}});recoveryToken='';renderLogin();document.getElementById('login-username').value=d.email||d.username;toast('Owner password saved. Sign in with your new password.');break;}
 case 'admin-email':{const d=await api('/api/admin/email',{method:'PATCH',body:b});state.admin={...state.admin,...d};toast('Login email saved.');await loadAdminTab();break;}
 case 'admin-team-create':case 'admin-team-manage':{await api('/api/admin/team',{method:'POST',body:{...b,action:type==='admin-team-create'?'create':b.action}});toast('Team account updated.');await loadAdminTab();break;}
 case 'admin-login':{const d=await api('/api/admin/login',{method:'POST',body:b});state.admin=d;state.adminTab='overview';renderAdmin();toast('Signed in successfully.');break;}
 case 'admin-settings':{await api('/api/admin/settings',{method:'PATCH',body:b});state.config=await api('/api/config');toast('Public business settings saved.');break;}
 case 'admin-product':{const id=f.dataset.id;const values={...b,price:Number(b.price),stock:Number(b.stock),active:b.active==='1',featured:b.featured==='1',sample:b.sample==='1'};await api(id?'/api/admin/products/'+id:'/api/admin/products',{method:id?'PUT':'POST',body:values});closeDialog();toast('Part listing saved.');await loadAdminTab();state.products=(await api('/api/products?limit=100')).items;break;}
 case 'admin-service':{const vals={...b,id:b.id?Number(b.id):null,active:b.active==='1',sort_order:Number(b.sort_order)};await api('/api/admin/services',{method:'POST',body:vals});closeDialog();toast('Repair service saved.');await loadAdminTab();state.config=await api('/api/config');break;}
 case 'admin-models':{const rows=b.lines.split(/\r?\n/).map(l=>l.trim()).filter(Boolean).map(l=>{const idx=l.indexOf(',');return {brand:idx>=0?l.slice(0,idx).trim():'',model:idx>=0?l.slice(idx+1).trim():''};});if(rows.some(x=>!x.brand||!x.model))throw new Error('Each line must contain Brand, Model.');const d=await api('/api/admin/models/bulk',{method:'POST',body:{models:rows}});toast(`${d.added} new models imported.`);await loadAdminTab();state.config=await api('/api/config');break;}
 case 'admin-password':{await api('/api/admin/password',{method:'PATCH',body:b});f.reset();toast('Password updated. Other sessions signed out.');break;}
 }
 }catch(e){toast(e.message,true);if(['admin-login','admin-recovery'].includes(type)){const el=document.getElementById('access-error');if(el){el.hidden=false;el.textContent=e.message;}}if(type==='track'){document.getElementById('track-result').innerHTML=`<div class="status-note" style="border-color:#f7bdaf;background:#fff7f5;color:#b04a38;margin-top:17px">${icon('info',18)} ${esc(e.message)}</div>`;}}
 finally{if(button?.isConnected)loadingButton(button,false);}
});
window.addEventListener('popstate',route);
window.addEventListener('scroll',updateNavbar,{passive:true});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog();});
async function bootstrap(){try{const [config,products]=await Promise.all([api('/api/config'),api('/api/products?limit=100')]);state.config=config;state.products=products.items;await route();}catch(e){app.innerHTML=`<section class="boot"><div style="text-align:center;padding:25px;max-width:460px"><h2>Unable to load the storefront</h2><p style="color:#bac8cd">${esc(e.message)}. Please check that the RepairlyLabs server is running.</p><button class="btn btn-primary" data-action="retry">Try again</button></div></section>`;}}
bootstrap();
